import{A as e,B as t,V as n,et as r}from"./chunks/framework.COrJTECx.js";var i=JSON.parse(`{"title":"Autossential.Activities","description":"","frontmatter":{},"headers":[],"relativePath":"core/changelog.md","filePath":"core/changelog.md"}`),a={name:`core/changelog.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="autossential-activities" tabindex="-1">Autossential.Activities <a class="header-anchor" href="#autossential-activities" aria-label="Permalink to “Autossential.Activities”">​</a></h1><h2 id="_4-0-11-2026-09-19" tabindex="-1">4.0.11 - 2026.09.19 <a class="header-anchor" href="#_4-0-11-2026-09-19" aria-label="Permalink to “4.0.11 - 2026.09.19”">​</a></h2><p>Fixed the <strong>Wait File</strong> activity for dynamic file wait logic so it can recover when a temporary file is renamed while it is still locked/in use.</p><p>Fixed <strong>Promote Headers</strong> activity for empty cells and duplicate auto-renaming:</p><ul><li>Fixed duplicate header auto-renaming when some column names are empty.</li><li>Previously empty names could produce incorrect/unstable generated names; now empty headers are normalized to a consistent pattern like “Col”, “Col1”, etc., while still avoiding duplicates.</li></ul><h2 id="_4-0-10-2026-08-31" tabindex="-1">4.0.10 - 2026.08.31 <a class="header-anchor" href="#_4-0-10-2026-08-31" aria-label="Permalink to “4.0.10 - 2026.08.31”">​</a></h2><p>Moved <strong>Time Loop</strong> execution state into WF implementation variables to prevent state leakage between reused instances. Turned Result property visible in the properties designer.</p><h2 id="_4-0-9-2026-08-02" tabindex="-1">4.0.9 - 2026.08.02 <a class="header-anchor" href="#_4-0-9-2026-08-02" aria-label="Permalink to “4.0.9 - 2026.08.02”">​</a></h2><p>The <strong>Exit</strong> activity now displays its condition directly within the activity card.</p><h2 id="_4-0-8-2026-07-19" tabindex="-1">4.0.8 - 2026.07.19 <a class="header-anchor" href="#_4-0-8-2026-07-19" aria-label="Permalink to “4.0.8 - 2026.07.19”">​</a></h2><p><strong>UnmapDrive Activity Enhancement</strong></p><p>Added new AllDrives boolean property to unmaps all mapped network drives at once (previously only supported single drive unmapping).</p><p><strong>Add Range To Collection &amp; Update Dictionary</strong></p><p>Fixed auto-type identification issues in both activities</p><h2 id="_4-0-7-2026-06-28" tabindex="-1">4.0.7 - 2026.06.28 <a class="header-anchor" href="#_4-0-7-2026-06-28" aria-label="Permalink to “4.0.7 - 2026.06.28”">​</a></h2><p>Updated missing property descriptions for <strong>Time Loop</strong>.Result and <strong>Map Drive</strong>.Credential.</p><h2 id="_4-0-6-2026-06-21" tabindex="-1">4.0.6 - 2026.06.21 <a class="header-anchor" href="#_4-0-6-2026-06-21" aria-label="Permalink to “4.0.6 - 2026.06.21”">​</a></h2><p><strong>Clean Up Folder</strong> updated to consider readonly files during clean up.</p><h2 id="_4-0-5-2026-06-07" tabindex="-1">4.0.5 - 2026.06.07 <a class="header-anchor" href="#_4-0-5-2026-06-07" aria-label="Permalink to “4.0.5 - 2026.06.07”">​</a></h2><p>Design time fix when browsing folder/file that was creating long relative paths.</p><h2 id="_4-0-4-2026-05-26" tabindex="-1">4.0.4 - 2026.05.26 <a class="header-anchor" href="#_4-0-4-2026-05-26" aria-label="Permalink to “4.0.4 - 2026.05.26”">​</a></h2><p><strong>Wait File</strong> activity timeout has been fixed.</p><h2 id="_4-0-3-2026-05-09" tabindex="-1">4.0.3 - 2026.05.09 <a class="header-anchor" href="#_4-0-3-2026-05-09" aria-label="Permalink to “4.0.3 - 2026.05.09”">​</a></h2><p><strong>Map Drive</strong> and <strong>Unmap Drive</strong> activities can now show a dropdown to select the available drive letters.</p><p>Updated wrong descriptions in the Resources.resx.</p><h2 id="_4-0-2-2026-05-03" tabindex="-1">4.0.2 - 2026.05.03 <a class="header-anchor" href="#_4-0-2-2026-05-03" aria-label="Permalink to “4.0.2 - 2026.05.03”">​</a></h2><p>DataNode model now uses <code>IList&lt;T&gt;</code> instead of <code>List&lt;T&gt;</code> in the methods <code>AsSequence</code> and <code>AsSequenceOrDefault</code></p><h2 id="_4-0-1-2026-04-16" tabindex="-1">4.0.1 - 2026.04.16 <a class="header-anchor" href="#_4-0-1-2026-04-16" aria-label="Permalink to “4.0.1 - 2026.04.16”">​</a></h2><p>Removed the restriction of positive-only numbers in the <strong>Increment/Decrement</strong> activity.</p><h2 id="_4-0-0-2026-04-11" tabindex="-1">4.0.0 - 2026.04.11 <a class="header-anchor" href="#_4-0-0-2026-04-11" aria-label="Permalink to “4.0.0 - 2026.04.11”">​</a></h2><p>The redesigned Autossential.Activities package is tailored for the latest UiPath versions.</p><p>This release introduces 26 activities, each built to leverage the UiPath ViewModel for enhanced design-time rendering.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};